W=$HOME/work/loop; for r in $W/runs/s[pg]*/; do n=$(basename $r); [ -e $r/results.jsonl ] && echo "$n:$(wc -l < $r/results.jsonl)"; done | tr "\n" " "; echo; ls $W/pub/rows 2>/dev/null | grep -v log | sed "s/-[0-9]*\.npz//" | sort | uniq -c | tr "\n" " "; echo; ls $W/pub/rows-cut 2>/dev/null | tr "\n" " "; echo; git -C $W/src log -1 --format=%h; systemctl cat loop-rows 2>/dev/null | grep ExecStart | cut -c1-300
